@js:
// 1234验证
if(java.getString('.title@text').indexOf('防止恶意访问')>-1){
java.log('1234验证: '+java.ajax(
baseUrl+',{"body":"action=1&v=1234","method":"POST"}'
));
		src = java.ajax(baseUrl);
		java.setContent(src);
	}


// 字体防盗
if(src.match(/<i>&#xe[0-9a-z]{3};?<\/i>/i)){
z = "的一是了我不人在他有这个上们来到时大地为子中你说生国年着就那和要她出也得里后自以会家可下而过天去能对小多然于心学么之都好看起发当没成只如事把还用第样道想作种开美总从无情己面最女但现前些所同日手又行意动";
for(i=0;i<z.length;i++){
		reg = new RegExp('<i>&#xe'+(i+2048).toString(16)+';?</i>','g');
		src = src.replace(reg, z[i]);
	}
java.setContent(src);
}


// 获取正文
		result = String(java.getString('.neirong@html')).replace(/<center class="chapterPages">[\s\S]*/,'');


// 二次加载(beta
if(src.match(/\$.post\('',{'j':'1'}/)){
		result += java.ajax(baseUrl+',{"body":"j=1","method":"POST"}')
	}


// 正文解密
try{// 排序解密
		ns = src.match(/var ns='(.+?)';/)[1];
		ns = java.base64Decode(ns).split(',');
		t = result.split('<br><br>');
		result = "";
		for(i=0;i<t.length;i++){
				result += t[ ns[i+1]-ns[0] ]+'<br><br>';
			}
	}
catch(err){// AES解密
try{
function secret(string, code, operation) {
		code = java.md5Encode(code);
		var iv = code.substring(0, 16);
		var key = code.substring(16);
		return  result = java.createSymmetricCrypto("AES/CBC/PKCS7Padding", key, iv).decryptStr(string);
	}
		eval(src.match(/=\s*(secret\([\s\S]+?\);)\s*\$\(/)[1]);
	}
catch(err){}
}


// 章节加载失败，尝试补救
if(src.indexOf('Undefined index')>-1){
try{
baseUrl += ','+JSON.stringify({
  "body": "err=1",
  "charset": "UTF-8",
  "headers": {
    "referer": baseUrl
  },
  "method": "POST"
});
java.log('errurl: '+baseUrl)
result = String(java.ajax(baseUrl));
	}
catch(err){}
}


// 补救失败
if(/Undefined/.exec(result)){
		result = "<br>　　网站分页后第三页有时有问题不可用，速度慢的时候就会是现在这样了，网站速度快的时候就没事了。<br>　　换个时间刷新试试！！！<br>　　换个时间刷新试试！！！<br>　　换个时间刷新试试！！！<br>" + result;
	}


// 替换净化
x=(a,b)=>result=String(result).replace(a,b);

// 转换字符
x(/&?nbsp;/g,' ');
x(/&?lt;/g,'<');
x(/&?gt;/g,'>');

// 标记图片
x(/\s*<img[^>]+toimg\/data\/([^\.]+)[^>]+>\s*/gi,"#$1#");

// 分段换行
x(/\s*((\n|<br\/?>)+\s*)+\s*/gi,'\n\t\t');

// 删除标签
x(/<\/?[a-z]+[^>]*>/g,'');


'\n\t\t'+result+'hereispagebreak';

